package com.chesspulseai.engine; import com.chesspulseai.config.EngineProperties; import com.chesspulseai.exception.EngineUnavailableException; import jakarta.annotation.*; import java.io.*; import java.nio.charset.StandardCharsets; import java.util.*; import org.springframework.stereotype.Service; import org.slf4j.*;
@Service public class StockfishClient { private static final Logger log=LoggerFactory.getLogger(StockfishClient.class); private final EngineProperties props; private Process process; private BufferedWriter writer; private BufferedReader reader; public StockfishClient(EngineProperties p){props=p;} @PostConstruct synchronized void start(){if(!props.enabled()) return;if(props.path()==null||props.path().isBlank()) throw new EngineUnavailableException("STOCKFISH_PATH is required when STOCKFISH_ENABLED=true");try{process=new ProcessBuilder(props.path()).redirectErrorStream(true).start();writer=new BufferedWriter(new OutputStreamWriter(process.getOutputStream(),StandardCharsets.UTF_8));reader=new BufferedReader(new InputStreamReader(process.getInputStream(),StandardCharsets.UTF_8));send("uci");waitFor("uciok");send("isready");waitFor("readyok");log.info("Stockfish started");}catch(IOException e){throw new EngineUnavailableException("Unable to start Stockfish: "+e.getMessage());}} public synchronized EngineEvaluation evaluate(String fen){if(!props.enabled()||process==null||!process.isAlive())throw new EngineUnavailableException("Stockfish is not configured or unavailable");try{send("position fen "+fen);send("go depth "+props.depth());String best=null,pv="";Integer cp=null,mate=null;int depth=0;String line;while((line=reader.readLine())!=null){if(line.startsWith("info ")){String[] t=line.split(" ");for(int i=0;i<t.length-1;i++){if(t[i].equals("depth"))depth=Integer.parseInt(t[++i]);else if(t[i].equals("score")&&i+2<t.length){String type=t[++i], value=t[++i];if(type.equals("cp"))cp=Integer.parseInt(value); if(type.equals("mate"))mate=Integer.parseInt(value);}else if(t[i].equals("pv")){pv=String.join(" ",Arrays.copyOfRange(t,i+1,t.length));break;}}}if(line.startsWith("bestmove")){best=line.split(" ")[1];break;}}return new EngineEvaluation(cp,mate,best,pv,depth);}catch(Exception e){log.warn("Stockfish evaluation failed",e);throw new EngineUnavailableException("Stockfish evaluation failed");}} private void send(String s)throws IOException{writer.write(s);writer.newLine();writer.flush();} private void waitFor(String expected)throws IOException{String l;while((l=reader.readLine())!=null)if(l.equals(expected))return;throw new IOException("Stockfish exited during handshake");} @PreDestroy synchronized void stop(){if(process==null)return;try{send("quit");}catch(Exception ignored){}process.destroy();log.info("Stockfish stopped");}}

